import sys
from collections import defaultdict, deque

def topological_sort(packages, dependencies):
    graph = defaultdict(list)
    in_degree = {pkg: 0 for pkg in packages}

    for pkg, deps in dependencies.items():
        for dep in deps:
            graph[dep].append(pkg)
            in_degree[pkg] += 1

    queue = deque([pkg for pkg in in_degree if in_degree[pkg] == 0])
    result = []

    while queue:
        queue = deque(sorted(queue))
        current = queue.popleft()
        result.append(current)
        for neighbor in graph[current]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                queue.append(neighbor)

    if len(result) == len(packages):
        return result
    else:
        return 'cannot be ordered'

def main():
    input = sys.stdin.read().strip().split('\n')
    index = 0

    while index < len(input):
        n = int(input[index])
        if n == 0:
            break
        index += 1

        packages = []
        dependencies = {}

        for _ in range(n):
            line = input[index].split()
            pkg = line[0]
            deps = line[1:]
            packages.append(pkg)
            dependencies[pkg] = deps
            index += 1

        result = topological_sort(packages, dependencies)
        if result == 'cannot be ordered':
            print(result)
        else:
            print('\n'.join(result))
        print()

main()
